package com.quickmanager.model;

public class CanhBaoTonKho {
    private int maSanPham;
    private String tenSanPham;
    private int tonKho;
    private int mucToiThieu;
    private String trangThai;

    public CanhBaoTonKho(int maSanPham, String tenSanPham, int tonKho, int mucToiThieu, String trangThai) {
        this.maSanPham = maSanPham;
        this.tenSanPham = tenSanPham;
        this.tonKho = tonKho;
        this.mucToiThieu = mucToiThieu;
        this.trangThai = trangThai;
    }

    public int getMaSanPham() { return maSanPham; }
    public String getTenSanPham() { return tenSanPham; }
    public int getTonKho() { return tonKho; }
    public int getMucToiThieu() { return mucToiThieu; }
    public String getTrangThai() { return trangThai; }
}

package com.quickmanager.model;

import java.math.BigDecimal;
import java.time.LocalDate;

public class DoanhThuNgay {
    private LocalDate ngay;
    private int soHoaDon;
    private BigDecimal doanhThu;

    public DoanhThuNgay(LocalDate ngay, int soHoaDon, BigDecimal doanhThu) {
        this.ngay = ngay;
        this.soHoaDon = soHoaDon;
        this.doanhThu = doanhThu;
    }

    public LocalDate getNgay() { return ngay; }
    public int getSoHoaDon() { return soHoaDon; }
    public BigDecimal getDoanhThu() { return doanhThu; }
}

package com.quickmanager.model;

import java.math.BigDecimal;

public class TopSanPham {
	private String tenSanPham;
	private int soLuong;
	private BigDecimal doanhThu;

	public TopSanPham(String tenSanPham, int soLuong, BigDecimal doanhThu) {
		this.tenSanPham = tenSanPham;
		this.soLuong = soLuong;
		this.doanhThu = doanhThu;
	}

	public String getTenSanPham() { return tenSanPham; }
	public int getSoLuong() { return soLuong; }
	public BigDecimal getDoanhThu() { return doanhThu; }
}
